import type { GameId } from '../lib/routes';
import sizes from './asset-sizes.json';

export type ImageKind = 'cover' | 'shot';

/**
 * Intrinsic pixel sizes of the committed game images, generated by
 * `scripts/placeholders.mjs` and `scripts/import-shots.mjs`.
 *
 * These feed the `width`/`height` attributes so the browser reserves the right
 * box before an image loads. They are read from a generated file rather than
 * typed in because the placeholders and the real screenshots have different
 * aspect ratios — 720x1280 against 591x1280 for SumQuest — and hand-kept
 * numbers would go stale the moment real art landed, with layout shift as the
 * only symptom.
 */
// Typed as plain number arrays rather than tuples so the generated JSON is
// assignable without a cast; the pair is then checked where it is read, which
// is the only place a malformed entry could do damage.
const TABLE: Record<string, Partial<Record<ImageKind, number[]>>> = sizes;

export function assetSize(gameId: GameId, kind: ImageKind): { width: number; height: number } {
  const size = TABLE[gameId]?.[kind];
  if (!size || size.length !== 2) {
    throw new Error(
      `asset-sizes.json has no valid ${kind} size for "${gameId}" — run: node scripts/placeholders.mjs`,
    );
  }
  return { width: size[0], height: size[1] };
}
